new(81,'oblique-hough-chain','Oblique Hough normal and support',[1011,1012],'In a declared ideal Hough example, points are (u,v)=(2,0),(4,2),(6,4),(0,5). For the line through the first three, use θ∈[0,π) and signed ρ. What are (θ,ρ), its support, and acceptance under votes>2?',[('(45°,√2); 3 votes; accepted','45° is the line direction, not the normal for v=u−2.'),('(135°,√2); 3 votes; accepted','The normal angle is right but the signed offset is negative.'),('(135°,−√2); 4 votes; accepted','The fourth point does not satisfy v=u−2.'),('(135°,−√2); 3 votes; accepted','The normal is (−1,1)/√2, giving ρ=−√2 for the first three points.')],4,'The line is v=u−2, so θ=135° and ρ=−√2; exactly three points support it and 3>2.',['Derive v=u−2 from the first two points.','Normalize the coefficients −u+v=−2 to obtain normal (−1,1)/√2 and signed offset −√2.','Check the third point; reject (0,5) as an inlier to this exact line.','Three votes exceed 2; they would not exceed a strict threshold of 3.'],F_H,assumptions=['Use ideal exact geometry without quantized bins; this is not a claim about the literal OpenCV accumulator output.','The normal angle is measured in the stated coordinate axes, with v downward.'])
F_C=formula('A=Σ_i w_i g_i g_i^T; C=det(A)−α trace(A)²',{'w_i':'nonnegative normalized window weight','g_i':'column vector (Iu,Iv) at sample i','A':'weighted second-moment gradient matrix','C':'Harris response','α':'response coefficient'},{'w_i,α':'dimensionless','g_i':'intensity per pixel','A':'squared gradient units','C':'fourth-power gradient units'},['Use products of gradients before weighted summation, not the outer product of their mean.'])
new(82,'harris-weighted-products','Gradients to Harris matrix and score',[1014],'Three gradient vectors are (2,0),(0,2),(1,1), with weights 1/4,1/4,1/2. For A=Σw_i g_i g_iᵀ and α=0.04, what are A and C=det(A)−α trace(A)²?',[('A=[[1,1],[1,1]]; C=−0.16','This forms the outer product of the weighted mean gradient instead of the weighted second moments.'),('A=[[1.5,0.5],[0.5,1.5]]; C=1.64','Weighted squares give 1.5 on the diagonal and weighted products give 0.5 off it.'),('A=[[1.5,0],[0,1.5]]; C=1.89','This drops the cross-product term 0.5.'),('A=[[1.5,0.5],[0.5,1.5]]; C=1.88','This subtracts α trace(A) instead of α trace(A)².')],2,'A has diagonal entries 1.5 and off-diagonal entries 0.5; det(A)=2 and trace(A)=3, so C=2−0.04×9=1.64.',['Compute Σw Iu²=1+0+0.5=1.5 and Σw Iv²=0+1+0.5=1.5.','Compute Σw Iu Iv=0+0+0.5=0.5.','The determinant is 1.5²−0.5²=2 and trace is 3.','Subtract 0.04×3²=0.36 to obtain 1.64.'],[F_C],assumptions=['The supplied weights already sum to one; gradients are declared samples, not extracted from the source photograph.'])
